import * as React from "react";
import { Box, Card, CardContent, Typography, Grid, CardActionArea } from "@mui/material";

interface HomePageProps {
  onSelect: (page: string) => void;
}

const HomePage = ({ onSelect }: HomePageProps) => {
  const cards = [
    { label: "Venues", value: "venues" },
    { label: "Hair", value: "hair" },
    { label: "Makeup", value: "makeup" },
    { label: "Photographers", value: "photographers" },
    { label: "Music", value: "music" },
    { label: "Florist", value: "florist" },
    { label: "Dresser", value: "dresser" },
    { label: "Planner", value: "planner" },
  ];

  const handleCardClick = (page: string) => {
    onSelect(page); // Calls the onSelect function from the parent to change pages
  };

  return (
    <Box sx={{ padding: 2 }}>
      <Grid container spacing={2}>
        {cards.map((card) => (
          <Grid item xs={6} sm={4} md={3} key={card.value}> {/* Responsive grid with 2 columns on small screens */}
            <Card sx={{ boxShadow: 3 }}>
              <CardActionArea onClick={() => handleCardClick(card.value)}>
                <CardContent>
                  <Typography variant="h6" component="div" sx={{ fontWeight: "bold" }}>
                    {card.label}
                  </Typography>
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

export default HomePage;



